function PlaylistsNewInner() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.playlists.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push(`/playlists/${text(row.id)}`);
    }
  });
  return (
    <Pane title="New playlist">
      <PlaylistsForm
        fields={PLAYLISTS_CREATE}
        initial={EMPTY_PLAYLISTS}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate(toPlaylistsCreateInput(values))}
      />
    </Pane>
  );
}

